contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    // amount is the ETH forwarded to c.go. This contract must have enough balance to send it.
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance for test");

        // Observe owner's value before the call
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint256 balanceBefore = address(c).balance;

        // Invoke c.go forwarding amount and catch whether it reverts
        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Observe after-values
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint256 balanceAfter = address(c).balance;

        // General rule: if the call succeeded (did not revert) then c's balance is zero afterwards
        // and the owner getter remains unchanged.
        assert(reverted || (balanceAfter == 0 && ownerAfter == ownerBefore));
    }
    receive() external payable {}
}

